def parse_time(value):
    if not value:
        return None
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def display_time(value):
    moment = parse_time(value)
    if not moment:
        return "Not available"
    return moment.astimezone(DISPLAY_ZONE).strftime("%Y-%m-%d %H:%M WIB")


def listing_payload(row):
    details = json.loads(row.get("latest_json") or "{}")
    details.update(row)
    details["property_romaji"] = ROMAJI.get(details.get("property"), "")
    details["station_romaji"] = STATION_ROMAJI.get(details.get("primary_station"), "")
    details["access_options"] = [
        {
            **option,
            "station_romaji": STATION_ROMAJI.get(option.get("station"), ""),
        }
        for option in details.get("access_options", [])
    ]
    details.pop("latest_json", None)
    return details


def main():
    profile = load_profile()
    if PREFERENCES.exists():
        saved = json.loads(PREFERENCES.read_text(encoding="utf-8"))
        targets = saved.get("targets", {})
        profile["minimum_area_m2"] = targets.get("area_m2", profile["minimum_area_m2"])
        profile["maximum_station_walk_minutes"] = targets.get(
            "station_walk_minutes", profile["maximum_station_walk_minutes"]
        )
        profile["maximum_commute_minutes"] = targets.get(
            "total_commute_minutes", profile["maximum_commute_minutes"]
        )
    current = [listing_payload(row) for row in get_current_listings()]
    rows = [row for row in current if passes_hard_filters(row, profile)]
    crawl = get_latest_crawl_run()
    last_updated = crawl.get("finished_at") if crawl else max(
        (row.get("last_seen_at") for row in rows), default=None
    )
    updated_at = parse_time(last_updated) or datetime.now(timezone.utc)
    next_update = updated_at + timedelta(minutes=INTERVAL_MINUTES)
    payload = json.dumps(rows, ensure_ascii=False).replace("</", "<\\/")
    preferences = PREFERENCES.read_text(encoding="utf-8") if PREFERENCES.exists() else "{}"
    defaults = DEFAULT_PREFERENCES.read_text(encoding="utf-8") if DEFAULT_PREFERENCES.exists() else preferences
    generated = TEMPLATE.replace("__APARTMENTS__", payload)
    generated = generated.replace("__PREFERENCES__", preferences.replace("</", "<\\/"))
    generated = generated.replace("__DEFAULTS__", defaults.replace("</", "<\\/"))
    generated = generated.replace("__LAST_UPDATED__", html.escape(display_time(last_updated)))
    generated = generated.replace("__NEXT_UPDATE__", html.escape(display_time(next_update.isoformat())))
    generated = generated.replace("__COUNT__", str(len(rows)))
    generated = generated.replace("__CRAWL_STATUS__", html.escape(f'{crawl.get("rooms_found", 0)} search results · {len(rows)} verified available · {crawl.get("areas_requested", 0) - crawl.get("areas_failed", 0)}/{crawl.get("areas_requested", 0)} areas succeeded' if crawl else "No completed crawl"))
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(generated, encoding="utf-8")
    print(f"WATCHLIST={OUTPUT} LISTINGS={len(rows)}")


